WITH flattened AS (SELECT id, host, log_ts, latency_ms, status_code, key, value FROM app_logs LATERAL VIEW EXPLODE(context) x AS key, value) SELECT id, host, log_ts, latency_ms, key, LAG(latency_ms) OVER (PARTITION BY key, host ORDER BY status_code, id, key) prev_latency_ms, LEAD(status_code) OVER (PARTITION BY key, host ORDER BY status_code, id, key) next_status_code, ROW_NUMBER() OVER (PARTITION BY key, host ORDER BY status_code, id, key) event_seq FROM flattened WHERE key = 'version'
